# French, Italian and German for the site. Each row: English (the key), French, Italian, German.
# The English text must match the site exactly: for markup, the inner HTML of the lang="en" element;
# for scripts, the English argument of E.L(...). {0}, {1}… are names or numbers filled in at runtime.
# Game terms printed on the cards (Main Deck, Source Deck, keywords, card names) stay in English.
# Run:  python data/translations.py   ->  writes js/locales/fr.js, it.js, de.js
import json, os


def LM(*lines):
    """Headline split into animated lines. A line starting with * is italic."""
    out = []
    for l in lines:
        inner = f"<em>{l[1:]}</em>" if l.startswith("*") else l
        out.append(f'<span class="line-mask"><span>{inner}</span></span>')
    return "".join(out)


def KW(k):
    return f'<button type="button" class="kw" data-k="{k}">{k}</button>'


