if __name__ == "__main__":
    here = os.path.dirname(os.path.abspath(__file__))
    out_dir = os.path.join(here, "..", "js", "locales")
    os.makedirs(out_dir, exist_ok=True)
    for i, code in enumerate(["fr", "it", "de"], start=1):
        d = {}
        for row in ROWS:
            d[row[0]] = row[i]
        js = ("/* Generated by data/translations.py. Edit that file, not this one. */\n"
              "window.I18N = window.I18N || {};\n"
              f"window.I18N.{code} = " + json.dumps(d, ensure_ascii=False, indent=0) + ";\n")
        open(os.path.join(out_dir, f"{code}.js"), "w", encoding="utf-8").write(js)
        print(code, len(d))
